        const { sourceAnnotation: annotation } = evt.detail;
        if (this.toolName !== annotation?.metadata?.toolName ||
            !this.splineToolNames.includes(annotation?.metadata?.toolName) ||
            !this.configuration.simplifiedSpline) {
            return;
        }
